<?php defined('ABSPATH')||exit; global $wpdb; ?>
<h2><?php esc_html_e('Training Enrollments','kitmage-training-entitlements'); ?></h2>
<?php if(!$batches): ?><p><?php esc_html_e('No training entitlement purchases were found.','kitmage-training-entitlements'); ?></p><?php endif; ?>
<?php foreach($batches as $batch): $rows=$wpdb->get_results($wpdb->prepare("SELECT first_name_snapshot,last_name_snapshot,redeemed_at FROM {$wpdb->prefix}kte_redemptions WHERE batch_id=%d AND status='completed' ORDER BY redeemed_at",$batch->id));$usable='active'===$batch->status&&$batch->expires_at>current_time('mysql',true)&&((int)$batch->entitlements_used+(int)$batch->entitlements_reserved)<(int)$batch->entitlements_total;$raw=$usable?$tokens->decrypt($batch->encrypted_token):'';$url=$raw?$tokens->url($raw):''; ?>
<section class="woocommerce-order-details kte-batch"><h3><?php echo esc_html(get_the_title($batch->course_id)?:sprintf(__('Course #%d (unavailable)','kitmage-training-entitlements'),$batch->course_id)); ?></h3><p><?php printf(esc_html__('Order #%1$d · %2$d of %3$d used · Expires %4$s · %5$s','kitmage-training-entitlements'),$batch->order_id,$batch->entitlements_used,$batch->entitlements_total,esc_html(wp_date(get_option('date_format'),strtotime($batch->expires_at.' UTC'))),esc_html(ucfirst($batch->status))); ?></p>
<?php if($url): ?><p><a class="kte-link" href="<?php echo esc_url($url); ?>"><?php echo esc_html($url); ?></a> <button type="button" class="button kte-copy" data-url="<?php echo esc_attr($url); ?>"><?php esc_html_e('Copy Redemption Link','kitmage-training-entitlements'); ?></button></p><?php endif; ?>
<h4><?php esc_html_e('Trainees','kitmage-training-entitlements'); ?></h4><?php if(!$rows): ?><p><?php esc_html_e('No trainees have redeemed this batch.','kitmage-training-entitlements'); ?></p><?php else: ?><table class="woocommerce-table"><tbody><?php foreach($rows as $row): ?><tr><td><?php echo esc_html(trim($row->first_name_snapshot.' '.$row->last_name_snapshot)); ?></td><td><?php echo esc_html(wp_date(get_option('date_format'),strtotime($row->redeemed_at.' UTC'))); ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><?php endforeach; ?>
